const catalog=(revision=3,options=filterOptions)=>({schemaVersion:2,datasetEpoch:'epoch-1',appliedRevision:revision,coverage:{fidelity:'exact',observed:7,eligible:7},metrics:[{key:'recorded_tokens',formulaVersion:1,unit:'tokens',dimensions:[]}],filterOptions:options})
