const reviewSpec={reviewId:'review-demo',datasetEpoch:'epoch-1',indexRevision:3,scope:{kind:'single_session' as const,rootSessionId:'root-opaque'},model:'gpt-5.6-sol',reasoning:'high'}
const reviewPlan={schemaVersion:3,datasetEpoch:'epoch-1',appliedRevision:3,planId:'plan-demo',review:reviewSpec,launchPrompt:'Use $codex-inspector:review-session. Investigate the selected local scope; do not expect a precomputed manifest.'}
const projectReviewPlan={...reviewPlan,review:{...reviewSpec,scope:{kind:'time_period' as const,start:'2026-07-01T00:00:00Z',end:'2026-07-02T00:00:00Z',timezone:'UTC',projectId:'project-1'},projectName:'Inspector'}}
const completeReview={summary:{reviewId:'review-demo',status:'complete',createdAt:'2026-07-18T12:00:00Z',threadId:'thread-demo'},review:reviewSpec,run:{schemaVersion:'inspector.review/v1',reviewId:'review-demo',status:'complete',createdAt:'2026-07-18T12:00:00Z',startedAt:'2026-07-18T12:00:01Z',completedAt:'2026-07-18T12:01:00Z',threadId:'thread-demo',launchPromptVersion:'inspector.review-launch/v2',command:['codex','exec'],acceptedReportSha256:'c'.repeat(64),diagnostics:[],review:reviewSpec},reportState:'accepted',acceptedReport:{schemaVersion:'inspector.review/v1',reviewId:'review-demo',scope:{kind:'single_session',summary:'One root and descendants.',datasetEpoch:'epoch-1',indexRevision:3},model:'gpt-demo',reasoning:'high',completedAt:'2026-07-18T12:01:00Z',summary:'The task was effective with one opportunity.',findings:[{findingId:'finding-1',kind:'opportunity',lens:'task_framing_and_steering',title:'State acceptance first',observation:'Acceptance was implicit.',impact:'Rework was possible.',support:'directly_observed',evidenceSummary:'The cited event records the opening request.',citations:[{evidenceId:'evidence-message',sourcePrefixSha256:'a'.repeat(64),eventFingerprint:'b'.repeat(64),availability:'available',availabilityObservedAt:'2026-07-18T00:00:00Z',availabilityRevision:3,rootSessionId:'root-opaque',turnId:'turn-opaque'}],recommendation:'State acceptance before implementation.',actionPrompt:'Draft acceptance criteria only.'}],contentSha256:'c'.repeat(64)}}
function reviewMock(detail:unknown=completeReview,plan:unknown=reviewPlan){const value=detail as {summary:unknown};return vi.spyOn(globalThis,'fetch').mockImplementation(async(input,init)=>{const url=String(input);if(url==='/v1/status')return new Response(JSON.stringify(status()));if(url.startsWith('/v1/metrics/catalog'))return new Response(JSON.stringify(catalog()));if(url==='/v1/metrics/query')return new Response(JSON.stringify(metrics()));if(url==='/v1/review-plans')return new Response(JSON.stringify(plan));if(url==='/v1/reviews'&&init?.method==='POST')return new Response(JSON.stringify({reviewId:'review-demo',status:'planned',createdAt:'2026-07-18T12:00:00Z'}),{status:202});if(url==='/v1/reviews?pageSize=50')return new Response(JSON.stringify({items:[value.summary]}));if(url==='/v1/reviews/review-demo')return new Response(JSON.stringify(detail));return new Response(null,{status:204})})}

describe('Effectiveness Reviews',()=>{
 it('explains how Codex helps users improve and shows saved reviews without starting Codex',async()=>{history.replaceState(null,'','/reviews');const f=reviewMock();render(<App/>);expect(await screen.findByRole('heading',{name:'Learn from your Codex work'})).toBeInTheDocument();expect(screen.getByText('Use Codex to improve how you use Codex')).toBeInTheDocument();expect(screen.queryByText('PERSISTED CODEX TASKS')).not.toBeInTheDocument();expect(await screen.findByText('review-demo')).toBeInTheDocument();expect(f.mock.calls.some(c=>String(c[0])==='/v1/reviews'&&c[1]?.method==='POST')).toBe(false)})
 it('previews the exact prompt and requires a separate confirmation click',async()=>{history.replaceState(null,'','/reviews/new?session=root-opaque');const f=reviewMock();render(<App/>);expect(await screen.findByDisplayValue('root-opaque')).toBeInTheDocument();const model=screen.getByLabelText('Model');expect(model).toHaveValue('gpt-5.6-sol');expect(model.tagName).toBe('SELECT');fireEvent.click(screen.getByText('Preview review'));expect(await screen.findByText('See what Codex will be asked')).toBeInTheDocument();expect(screen.getByText(/Ready to learn from this work/)).toBeInTheDocument();expect(screen.getByText(/\$codex-inspector:review-session/)).toBeInTheDocument();expect(screen.getByText(/do not expect a precomputed manifest/)).toBeInTheDocument();const planRequest=f.mock.calls.find(c=>String(c[0])==='/v1/review-plans');const request=JSON.parse(String(planRequest?.[1]?.body));expect(request.scope).toEqual({kind:'single_session',rootSessionId:'root-opaque'});expect(request.model).toBe('gpt-5.6-sol');expect(f.mock.calls.some(c=>String(c[0])==='/v1/reviews'&&c[1]?.method==='POST')).toBe(false);fireEvent.click(screen.getByText('Start review with Codex'));await waitFor(()=>expect(location.pathname).toBe('/reviews/review-demo'));expect(location.search).toBe('?submitted=1');expect(await screen.findByRole('status')).toHaveTextContent('Review submitted');expect(screen.getByText('review-demo',{selector:'code'})).toBeInTheDocument();const launch=f.mock.calls.find(c=>String(c[0])==='/v1/reviews'&&c[1]?.method==='POST');expect(JSON.parse(String(launch?.[1]?.body))).toEqual({planId:'plan-demo',confirmed:true})})
 it('uses canonical project choices in the generated prompt',async()=>{history.replaceState(null,'','/reviews/new');const f=reviewMock(completeReview,projectReviewPlan);render(<App/>);const project=await screen.findByLabelText('Project');expect(screen.getByRole('option',{name:'Inspector'})).toHaveValue('project-1');fireEvent.change(project,{target:{value:'project-1'}});fireEvent.click(screen.getByText('Preview review'));expect(await screen.findByText('See what Codex will be asked')).toBeInTheDocument();const call=f.mock.calls.find(c=>String(c[0])==='/v1/review-plans');const request=JSON.parse(String(call?.[1]?.body));expect(request.scope.projectId).toBe('project-1');expect(request.scope.kind).toBe('time_period');expect(screen.getAllByText('Inspector').length).toBeGreaterThan(0)})
 it('renders accepted findings, citation return, task handoff, and copy-only action prompt',async()=>{history.replaceState(null,'','/reviews/review-demo');reviewMock();const writeText=vi.fn().mockResolvedValue(undefined);vi.stubGlobal('navigator',{...navigator,clipboard:{writeText}});render(<App/>);expect(await screen.findByText('State acceptance first')).toBeInTheDocument();expect(screen.getByRole('link',{name:'Open in Codex'})).toHaveAttribute('href','codex://threads/thread-demo');expect(screen.getByText('codex resume thread-demo')).toBeInTheDocument();expect(screen.getByRole('link',{name:'Open cited event'}).getAttribute('href')).toContain('return=%2Freviews%2Freview-demo');fireEvent.click(screen.getByText('Copy action prompt'));expect(writeText).toHaveBeenCalledWith('Draft acceptance criteria only.');expect(screen.getByText(/Inspector did not run it/)).toBeInTheDocument()})
 it('keeps malformed output visible and diagnosable',async()=>{history.replaceState(null,'','/reviews/review-demo');const invalid={...completeReview,summary:{...completeReview.summary,status:'unrenderable'},run:{...completeReview.run,status:'unrenderable',failureCode:'report_invalid',failureMessage:'review.json does not satisfy the frozen report contract.'},reportState:'unrenderable',acceptedReport:null};reviewMock(invalid);render(<App/>);expect(await screen.findByText('Report cannot be rendered')).toBeInTheDocument();expect(screen.getByText('report_invalid')).toBeInTheDocument();expect(screen.getByText(/remain local for diagnosis/)).toBeInTheDocument()})
})
